//! Environment Configuration Loader
//!
//! Loads environment variables from the canonical location: `/etc/op-dbus/environment`
//! This ensures all op-dbus components share the same configuration.
//!
//! ## Usage
//!
//! Call `load_environment()` early in main() before accessing any config:
//!
//! ```rust
//! use op_core::config::load_environment;
//!
//! fn main() {
//!     load_environment();
//!     // Now all env vars from /etc/op-dbus/environment are available
//! }
//! ```

use std::fs;
use std::path::Path;
use tracing::{debug, info, warn};

/// Canonical D-Bus well-known bus name for the op-dbus system.
///
/// All components (op-dbus-mirror, projection_server, rovs_proxy, etc.)
/// must use this constant instead of hardcoding the string.
pub const OPDBUS_BUS_NAME: &str = "org.opdbus.v1.plugins";

/// Default path for the environment file
pub const DEFAULT_ENV_FILE: &str = "/etc/op-dbus/environment";

/// Alternative paths to check (in order of priority)
pub const ENV_FILE_PATHS: &[&str] = &["/etc/op-dbus/environment", "/etc/op-dbus.env", ".env"];

/// Load environment variables from the canonical configuration file.
///
/// This function:
/// 1. Checks `/etc/op-dbus/environment` first (system-wide)
/// 2. Falls back to `.env` in current directory (development)
/// 3. Does NOT override existing environment variables
///
/// Returns the path that was loaded, or None if no file was found.
pub fn load_environment() -> Option<String> {
    // Check if a custom path is specified
    if let Ok(custom_path) = std::env::var("OP_ENV_FILE") {
        if let Some(path) = try_load_env_file(&custom_path) {
            return Some(path);
        }
    }

    // Try each path in order
    for path in ENV_FILE_PATHS {
        if let Some(loaded_path) = try_load_env_file(path) {
            return Some(loaded_path);
        }
    }

    debug!("No environment file found, using existing environment");
    None
}

/// Try to load an environment file from the given path.
fn try_load_env_file(path: &str) -> Option<String> {
    let path_obj = Path::new(path);

    if !path_obj.exists() {
        return None;
    }

    match fs::read_to_string(path_obj) {
        Ok(content) => {
            let mut loaded_count = 0;
            let mut skipped_count = 0;

            for line in content.lines() {
                let line = line.trim();

                // Skip comments and empty lines
                if line.is_empty() || line.starts_with('#') {
                    continue;
                }

                // Parse KEY=VALUE
                if let Some((key, value)) = parse_env_line(line) {
                    // Don't override existing environment variables
                    if std::env::var(&key).is_err() {
                        std::env::set_var(&key, &value);
                        loaded_count += 1;
                        debug!(
                            "Loaded: {}={}",
                            key,
                            if key.contains("KEY")
                                || key.contains("TOKEN")
                                || key.contains("SECRET")
                            {
                                "***"
                            } else {
                                &value
                            }
                        );
                    } else {
                        skipped_count += 1;
                        debug!("Skipped (already set): {}", key);
                    }
                }
            }

            info!(
                "Loaded {} environment variables from {} ({} skipped - already set)",
                loaded_count, path, skipped_count
            );

            Some(path.to_string())
        }
        Err(e) => {
            warn!("Failed to read environment file {}: {}", path, e);
            None
        }
    }
}

/// Parse a single environment line into key-value pair.
fn parse_env_line(line: &str) -> Option<(String, String)> {
    // Handle: KEY=VALUE, KEY="VALUE", KEY='VALUE'
    let mut parts = line.splitn(2, '=');
    let key = parts.next()?.trim();
    let value = parts.next()?.trim();

    if key.is_empty() {
        return None;
    }

    // Remove surrounding quotes
    let value = value
        .strip_prefix('"')
        .and_then(|v| v.strip_suffix('"'))
        .or_else(|| value.strip_prefix('\'').and_then(|v| v.strip_suffix('\'')))
        .unwrap_or(value);

    Some((key.to_string(), value.to_string()))
}

/// Get a configuration value with a default.
pub fn get_config(key: &str, default: &str) -> String {
    std::env::var(key).unwrap_or_else(|_| default.to_string())
}

/// Get an optional configuration value.
pub fn get_config_opt(key: &str) -> Option<String> {
    std::env::var(key).ok().filter(|v| !v.is_empty())
}

/// Get a boolean configuration value.
pub fn get_config_bool(key: &str, default: bool) -> bool {
    std::env::var(key)
        .map(|v| matches!(v.to_lowercase().as_str(), "true" | "1" | "yes" | "on"))
        .unwrap_or(default)
}

/// Get an integer configuration value.
pub fn get_config_int(key: &str, default: i64) -> i64 {
    std::env::var(key)
        .ok()
        .and_then(|v| v.parse().ok())
        .unwrap_or(default)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_parse_env_line_simple() {
        let (k, v) = parse_env_line("FOO=bar").unwrap();
        assert_eq!(k, "FOO");
        assert_eq!(v, "bar");
    }

    #[test]
    fn test_parse_env_line_quoted() {
        let (k, v) = parse_env_line("FOO=\"bar baz\"").unwrap();
        assert_eq!(k, "FOO");
        assert_eq!(v, "bar baz");
    }

    #[test]
    fn test_parse_env_line_single_quoted() {
        let (k, v) = parse_env_line("FOO='bar'").unwrap();
        assert_eq!(k, "FOO");
        assert_eq!(v, "bar");
    }

    #[test]
    fn test_parse_env_line_empty() {
        assert!(parse_env_line("").is_none());
        assert!(parse_env_line("=value").is_none());
    }
}

//! D-Bus object server for projections.
//!
//! Serves every Projection through org.opdbus.v1.plugins at
//! /org/opdbus/v1/plugins/<plugin>. Nothing mounts outside the plugins root:
//! no plugin means no schema means no object.

use anyhow::Result;
use std::collections::HashMap;
use std::sync::Arc;
use tokio::sync::RwLock;
use tracing::{debug, info};
use zbus::{connection::Builder, interface, object_server::SignalEmitter, Connection};

use crate::data_models::Projection;

/// A single projected object on the D-Bus object server.
pub struct ProjectedObject {
    pub entity_type: String,
    pub entity_id: String,
    /// JSON-serialized projection data
    pub data_json: Arc<RwLock<String>>,
    pub state: Arc<RwLock<String>>,
}

#[interface(name = "org.opdbus.v1.plugins.ProjectedObject")]
impl ProjectedObject {
    /// The schema/entity type for this object (e.g. "system.memory")
    #[zbus(property)]
    async fn entity_type(&self) -> &str {
        &self.entity_type
    }

    /// The unique entity ID within its type
    #[zbus(property)]
    async fn entity_id(&self) -> &str {
        &self.entity_id
    }

    /// Current projection state: Valid, Quarantined, Degraded, etc.
    #[zbus(property)]
    async fn state(&self) -> String {
        self.state.read().await.clone()
    }

    /// Full projection data as a JSON string
    #[zbus(property)]
    async fn data(&self) -> String {
        self.data_json.read().await.clone()
    }

    /// Signal emitted when this object's data changes
    #[zbus(signal)]
    async fn updated(emitter: &SignalEmitter<'_>, data_json: &str) -> zbus::Result<()>;
}

/// Derives the D-Bus object path from a projection's entity_type and entity_id.
///
/// Every projected object lives under the single plugins root, and nested
/// objects live under the plugin that produced them. No plugin means no schema
/// means no object — nothing is ever mounted outside this path.
///
/// entity_type "mail_server", entity_id "mail_server"
///   → /org/opdbus/v1/plugins/mail_server
/// entity_type "plugin.object", entity_id "wireguard:/interfaces/0"
///   → /org/opdbus/v1/plugins/wireguard/interfaces/0
pub fn projection_path(entity_type: &str, entity_id: &str) -> String {
    if entity_type == "plugin.object" {
        if let Some((plugin_id, object_path)) = entity_id.split_once(':') {
            return plugin_object_path(plugin_id, object_path);
        }
    }

    op_plugins::canonical::plugin_path(if entity_id.is_empty() {
        entity_type
    } else {
        entity_id
    })
}

fn plugin_object_path(plugin_id: &str, object_path: &str) -> String {
    let mut path = op_plugins::canonical::plugin_path(plugin_id);

    for segment in object_path.split('/').filter(|segment| !segment.is_empty()) {
        path.push('/');
        path.push_str(&sanitize_path_segment(segment));
    }

    path
}

fn sanitize_path_segment(segment: &str) -> String {
    let sanitized: String = segment
        .chars()
        .filter_map(|c| {
            if c.is_ascii_alphanumeric() || c == '_' {
                Some(c)
            } else if c == '-' || c == '.' {
                Some('_')
            } else {
                None
            }
        })
        .take(255)
        .collect();

    if sanitized.is_empty() {
        "_".to_string()
    } else {
        sanitized
    }
}

/// Object state handles for updating in place
type ObjectHandles = (Arc<RwLock<String>>, Arc<RwLock<String>>);

/// Manages the set of D-Bus objects served for all projections.
pub struct ProjectionDbusServer {
    conn: Connection,
    /// path → data/state handles so we can update in place
    objects: HashMap<String, ObjectHandles>,
}

impl ProjectionDbusServer {
    pub async fn new() -> Result<Self> {
        let conn = match std::env::var("OP_DBUS_PROJECTION_BUS")
            .unwrap_or_else(|_| "system".to_string())
            .as_str()
        {
            "session" => {
                Builder::session()?
                    .name(op_plugins::canonical::BASE_SERVICE_NAME)?
                    .build()
                    .await?
            }
            _ => {
                Builder::system()?
                    .name(op_plugins::canonical::BASE_SERVICE_NAME)?
                    .build()
                    .await?
            }
        };

        info!(
            service = op_plugins::canonical::BASE_SERVICE_NAME,
            "D-Bus plugin projection connection established"
        );

        Ok(Self {
            conn,
            objects: HashMap::new(),
        })
    }

    pub async fn new_session() -> Result<Self> {
        let conn = Builder::session()?
            .name(op_plugins::canonical::BASE_SERVICE_NAME)?
            .build()
            .await?;

        info!(
            service = op_plugins::canonical::BASE_SERVICE_NAME,
            "D-Bus session plugin projection connection established"
        );

        Ok(Self {
            conn,
            objects: HashMap::new(),
        })
    }

    /// Register a projection as a D-Bus object (or update it if already registered).
    pub async fn upsert(&mut self, projection: &Projection) -> Result<()> {
        let path = projection_path(&projection.entity_type, &projection.entity_id);
        let data_json = simd_json::to_string(&projection.data).unwrap_or_else(|_| "{}".to_string());
        let state_str = format!("{:?}", projection.state);

        if let Some((data_handle, state_handle)) = self.objects.get(&path) {
            // Update existing object in place
            *data_handle.write().await = data_json.clone();
            *state_handle.write().await = state_str;

            // Emit the updated signal
            let iface_ref = self
                .conn
                .object_server()
                .interface::<_, ProjectedObject>(path.as_str())
                .await?;
            ProjectedObject::updated(iface_ref.signal_emitter(), &data_json).await?;

            debug!(path, "updated D-Bus projection object");
        } else {
            // Register new object
            let data_arc = Arc::new(RwLock::new(data_json));
            let state_arc = Arc::new(RwLock::new(state_str));

            let obj = ProjectedObject {
                entity_type: projection.entity_type.clone(),
                entity_id: projection.entity_id.clone(),
                data_json: data_arc.clone(),
                state: state_arc.clone(),
            };

            self.conn.object_server().at(path.as_str(), obj).await?;

            self.objects.insert(path.clone(), (data_arc, state_arc));
            debug!(path, entity_type = %projection.entity_type, "registered D-Bus projection object");
        }

        Ok(())
    }

    /// Remove a projection's D-Bus object.
    pub async fn remove(&mut self, entity_type: &str, entity_id: &str) -> Result<()> {
        let path = projection_path(entity_type, entity_id);
        if self.objects.remove(&path).is_some() {
            self.conn
                .object_server()
                .remove::<ProjectedObject, _>(path.as_str())
                .await?;
            info!(path, "removed D-Bus projection object");
        }
        Ok(())
    }

    pub fn object_count(&self) -> usize {
        self.objects.len()
    }
}

#[cfg(test)]
mod tests {
    use super::projection_path;

    #[test]
    fn projects_plugin_roots_under_canonical_plugin_path() {
        assert_eq!(
            projection_path("mail_server", "mail_server"),
            "/org/opdbus/v1/plugins/mail_server"
        );
        assert_eq!(
            projection_path("ovsdb_bridge", "ovsdb_bridge"),
            "/org/opdbus/v1/plugins/ovsdb_bridge"
        );
    }

    #[test]
    fn projects_nested_objects_under_owning_plugin() {
        assert_eq!(
            projection_path("plugin.object", "wireguard:/interfaces/0/peers"),
            "/org/opdbus/v1/plugins/wireguard/interfaces/0/peers"
        );
    }
}

//! op-openvswitch-daemon — Pure passthrough D-Bus proxy for rovs primitives.
//!
//! TWO separate D-Bus object paths (locked design):
//! - `/org/opdbus/rovs/jsonrpc`  → `org.opdbus.rovs.jsonrpc`
//! - `/org/opdbus/rovs/openflow` → `org.opdbus.rovs.openflow`
//!
//! The daemon is a literal passthrough: it owns the rovs crate connections
//! and exposes raw primitives over D-Bus.  Zero business logic.
//!
//! Per AGENTS.md §4: D-Bus is the ONLY control plane.

use anyhow::{Context, Result};
use std::path::Path;
use tracing::{info, warn};
use zbus::connection::Connection;

mod container;
mod dbus;
mod execution;
mod grpc;
mod grpc_streaming;
mod netns;

use dbus::{DaemonState, JsonRpcService, OpenFlowService, ProxyService};
use execution::PluginExecutionService;
use grpc_streaming::{EventBus, StreamingService};

// ── CLI ───────────────────────────────────────────────────────────────────────

#[derive(Debug, Clone)]
struct Args {
    grpc_addr: Option<String>,
    ovs_socket: Option<String>,
}

impl Args {
    fn parse() -> Self {
        let args: Vec<String> = std::env::args().collect();
        let mut grpc_addr = None;
        let mut ovs_socket = None;
        let mut i = 1;
        while i < args.len() {
            match args[i].as_str() {
                "--grpc" => {
                    if i + 1 < args.len() {
                        grpc_addr = Some(args[i + 1].clone());
                        i += 2;
                    } else {
                        i += 1;
                    }
                }
                "--ovs-socket" => {
                    if i + 1 < args.len() {
                        ovs_socket = Some(args[i + 1].clone());
                        i += 2;
                    } else {
                        i += 1;
                    }
                }
                _ => i += 1,
            }
        }
        Self {
            grpc_addr,
            ovs_socket,
        }
    }
}

// ── Socket discovery ────────────────────────────────────────────────────────

const DEFAULT_OVS_SOCKET: &str = "/usr/local/var/run/openvswitch/db.sock";
const OVS_SOCKET_PATHS: &[&str] = &[
    "/usr/local/var/run/openvswitch/db.sock",
    "/run/openvswitch/db.sock",
    "/var/run/openvswitch/db.sock",
];

fn find_ovs_socket() -> String {
    OVS_SOCKET_PATHS
        .iter()
        .find(|p| Path::new(p).exists())
        .unwrap_or(&DEFAULT_OVS_SOCKET)
        .to_string()
}

// ── Main ────────────────────────────────────────────────────────────────────

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(tracing_subscriber::EnvFilter::from_default_env())
        .init();

    info!("Starting op-openvswitch-daemon (pure passthrough)");

    let args = Args::parse();
    let socket_path = args.ovs_socket.unwrap_or_else(find_ovs_socket);
    info!("Using OVS socket: {}", socket_path);

    let state = DaemonState::new(socket_path);

    // Eager-connect OVSDB so early callers don't wait.
    if let Err(e) = state.get_ovsdb().await {
        warn!(
            "Could not connect to OVSDB: {}. Will retry on first request.",
            e
        );
    }

    // Connect to the op-dbus session bus (not the system bus).
    // op-dbus-mirror owns org.opdbus.v1 on a private session bus;
    // we must join that bus so our rovs/* objects are reachable.
    let session_bus_addr = std::env::var("DBUS_SESSION_BUS_ADDRESS")
        .unwrap_or_else(|_| "unix:path=/run/op-dbus/session-bus.sock".to_string());
    let conn = Connection::session()
        .await
        .context("Failed to connect to session D-Bus")?;
    info!("Connected to session D-Bus ({})", session_bus_addr);

    // Register TWO separate object paths (locked design).
    let grpc_state = state.clone();
    let json_service = JsonRpcService::new(state.clone());
    let of_service = OpenFlowService::new(state.clone());
    let proxy_service = ProxyService::new(state);

    conn.object_server()
        .at("/org/opdbus/rovs/jsonrpc", json_service)
        .await
        .context("Failed to register /org/opdbus/rovs/jsonrpc")?;

    conn.object_server()
        .at("/org/opdbus/rovs/openflow", of_service)
        .await
        .context("Failed to register /org/opdbus/rovs/openflow")?;

    conn.object_server()
        .at("/org/opdbus/rovs/proxy", proxy_service)
        .await
        .context("Failed to register /org/opdbus/rovs/proxy")?;

    let exec_service = PluginExecutionService::new();
    conn.object_server()
        .at("/org/opdbus/execution", exec_service)
        .await
        .context("Failed to register /org/opdbus/execution")?;

    // Request the ovsdb plugin bus name — NOT org.opdbus.v1 (owned by op-dbus-mirror).
    conn.request_name("org.opdbus.v1.plugins.ovsdb")
        .await
        .context("Failed to request bus name org.opdbus.v1.plugins.ovsdb")?;

    info!("D-Bus services registered:");
    info!("  /org/opdbus/rovs/jsonrpc  -> org.opdbus.rovs.jsonrpc");
    info!("  /org/opdbus/rovs/openflow -> org.opdbus.rovs.openflow");
    info!("  /org/opdbus/rovs/proxy    -> org.opdbus.rovs.proxy");
    info!("  /org/opdbus/execution     -> org.opdbus.execution");

    // Optional gRPC with streaming support (M2)
    if let Some(grpc_addr) = args.grpc_addr {
        let addr: std::net::SocketAddr = grpc_addr.parse().context("Invalid --grpc address")?;
        info!("Starting gRPC server on {}", addr);

        // Create shared event bus for streaming subscriptions
        let event_bus = EventBus::new();
        let streaming_service = StreamingService::new(grpc_state.clone(), event_bus);

        tokio::spawn(async move {
            if let Err(e) =
                grpc::run_grpc_server_with_streaming(addr, grpc_state, streaming_service).await
            {
                warn!("gRPC server error: {}", e);
            }
        });
    }

    info!("Daemon ready — Ctrl+C to stop");
    loop {
        tokio::time::sleep(tokio::time::Duration::from_secs(60)).await;
    }
}

            current_data: DashMap::new(),
            sessions: DashMap::new(),
        })
    }

    /// Attach a gRPC server so the ComponentRegistry is mirrored into D-Bus.
    pub fn with_grpc_server(mut self, grpc_server: Arc<OperationGrpcServer>) -> Self {
        self.grpc_server = Some(grpc_server);
        self
    }

    /// Attach the StateManager so all registered plugins are always visible in
    /// the managed objects tree (active or not).
    pub fn with_state_manager(mut self, state_manager: Arc<StateManager>) -> Self {
        self.state_manager = Some(state_manager);
        self
    }

    /// Start the mirror service.
    ///
    /// Performs an initial full-tree publication and then enters an event-driven
    /// loop to publish deltas from all data sources.
    pub async fn start(self: Arc<Self>) -> std::result::Result<(), MirrorError> {
        tracing::info!("Starting D-Bus mirror publication service...");

        // Register ObjectManager at the root to manage EVERYTHING.
        let om = ObjectManagerInterface::new(self.plugin_registry.clone());
        self.connection
            .object_server()
            .at("/org/opdbus/v1", om)
            .await?;

        // Register PluginsV1 at the canonical plugins path.
        let plugin_iface = plugin_interface::PluginInterface::new();
        let plugin_snap = plugin_iface.snapshot_handle();
        self.connection
            .object_server()
            .at("/org/opdbus/v1/plugins", plugin_iface)
            .await?;

        // Register mirror-management interface
        let interface = dbus_interface::DbusMirrorInterface::new(self.clone());
        self.connection
            .object_server()
            .at("/org/opdbus/v1", interface)
            .await?;

        // Register OVSDB JSON-RPC interface at /org/opdbus/v1/ovsdb
        let ovsdb_interface =
            jsonrpc_interface::OvsdbInterface::new(self.ovsdb.clone(), self.schema_engine.clone());
        self.connection
            .object_server()
            .at("/org/opdbus/v1/ovsdb", ovsdb_interface)
            .await?;

        self.connection
            .request_name(op_core::config::OPDBUS_BUS_NAME)
            .await?;

        // Initial full sync
        if let Err(e) = self.refresh_full_tree().await {
            tracing::error!("Initial D-Bus mirror sync failed: {}", e);
        }

        // Create event dispatcher
        let dispatcher = crate::event_dispatcher::EventDispatcher::new(
            self.clone(),
            self.ovsdb.clone(),
            self.state_manager.clone(),
            self.grpc_server.clone(),
        );

        // Spawn all event sources
        if let Err(e) = dispatcher.spawn_event_sources().await {
            tracing::error!("Failed to spawn event sources: {}", e);
        }

        // Spawn heartbeat task
        if let Err(e) =
            crate::heartbeat::spawn_heartbeat_task(self.clone(), dispatcher.broadcast_tx.clone())
                .await
        {
            tracing::error!("Failed to spawn heartbeat task: {}", e);
        }

        // Run event loop
        if let Err(e) = dispatcher.run_event_loop().await {
            tracing::error!("Event loop failed: {}", e);
        }

        // Populate fixed objects immediately on startup.
        self.refresh_plugin_snapshot(&plugin_snap).await;

        // Watch ComponentRegistry for live register/deregister events
        if let Some(grpc) = &self.grpc_server {
            let (_, mut rx) = grpc.registry_watch().await;
            let mirror = self.clone();
            tokio::spawn(async move {
                loop {
                    match rx.recv().await {
                        Ok(event) => mirror.apply_registry_event(event).await,
                        Err(tokio::sync::broadcast::error::RecvError::Lagged(n)) => {
                            tracing::warn!(
                                "ComponentRegistry watcher lagged by {} events, resyncing",
                                n
                            );
                            if let Err(e) = mirror.refresh_full_tree().await {
                                tracing::error!("Registry resync failed: {}", e);
                            }
                        }
                        Err(tokio::sync::broadcast::error::RecvError::Closed) => break,
                    }
                }
            });
        }

        std::future::pending::<()>().await;
        Ok(())
    }


